// ProntoPraIA - No de auditoria: recebe HTML do no HTTP Request e calcula nota 0-100
const results = [];

for (const item of $input.all()) {
  const j = item.json;
  const url = j.url || j.URL || 'URL desconhecida';
  // O HTTP Request com responseFormat=text devolve o HTML em `data`
  const raw = j.data ?? j.html ?? j.body ?? '';
  const html = typeof raw === 'string' ? raw : JSON.stringify(raw);

  let nota = 0;
  const faltando = [];

  // 1. <title> (+25)
  const hasTitle = /<title[^>]*>[\s\S]+?<\/title>/i.test(html);
  if (hasTitle) { nota += 25; } else { faltando.push('title'); }

  // 2. <meta property="og:image" (+25)
  const hasOgImage = /<meta[^>]+property=["']og:image["'][^>]*>/i.test(html);
  if (hasOgImage) { nota += 25; } else { faltando.push('og:image'); }

  // 3. <meta property="og:price:amount" (+25)
  const hasOgPrice = /<meta[^>]+property=["']og:price:amount["'][^>]*>/i.test(html);
  if (hasOgPrice) { nota += 25; } else { faltando.push('og:price:amount'); }

  // 4. <script type="application/ld+json" (+25)
  const hasJsonLd = /<script[^>]+type=["']application\/ld\+json["'][^>]*>/i.test(html);
  if (hasJsonLd) { nota += 25; } else { faltando.push('json-ld'); }

  if (nota > 100) nota = 100;

  // Status
  let status = 'Crítico';
  if (nota >= 75) status = 'Pronto';
  else if (nota >= 50) status = 'Básico';

  // Tenta extrair nome/preco/imagem reais do HTML para o JSON-LD sugerido
  let prodName = 'Produto exemplo';
  let prodImage = 'https://exemplo.com/imagem.jpg';
  const mTitle = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  if (mTitle && mTitle[1]) prodName = mTitle[1].trim().substring(0, 150);
  const mImg = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i);
  if (mImg && mImg[1]) prodImage = mImg[1];

  // JSON-LD sugerido (sempre gerado; se ja tem schema, serve como modelo padrao)
  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Product',
    'name': prodName,
    'image': prodImage,
    'description': 'Descricao do produto em ' + url,
    'brand': { '@type': 'Brand', 'name': 'Marca do produto' },
    'offers': {
      '@type': 'Offer',
      'url': url,
      'priceCurrency': 'BRL',
      'price': '0.00',
      'availability': 'https://schema.org/InStock'
    }
  };

  results.push({
    json: {
      url: url,
      nota: nota,
      status: status,
      faltando: faltando.join(', '),
      json_ld_sugerido: JSON.stringify(jsonLd)
    }
  });
}

return results;
